import sys

class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None

class BalancedTree:
    def __init__(self):
        self.root = None

    def insert(self, value):
        if not self.root:
            self.root = TreeNode(value)
        else:
            self._insert_recursive(self.root, value)

    def _insert_recursive(self, root, value):
        if value < root.value:
            if root.left:
                self._insert_recursive(root.left, value)
            else:
                root.left = TreeNode(value)
        else:
            if root.right:
                self._insert_recursive(root.right, value)
            else:
                root.right = TreeNode(value)

    def search(self, value):
        return self._search_recursive(self.root, value)

    def _search_recursive(self, root, value):
        if root is None:
            return False
        if root.value == value:
            return True
        if value < root.value:
            return self._search_recursive(root.left, value)
        return self._search_recursive(root.right, value)

