import itertools

class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bit_array = bytearray(size)
        self.bloom_filter = set()

    def add(self, item):
        for h in range(self.hash_count):
            digest = hashlib.md5((item + str(h)).encode()).digest()
            offset = digest[0] % self.size
            self.bit_array[offset] |= 1 << (offset % 32)

